--region public
function ActivityDirectDrawRewardContentNode:Refresh()
    self.dojo = self._directDrawComponent:GetDirectDrawHomeDojo()

    if isNull(self.dojo) or isNull(self.dojo.poolInfo) then
        return
    end
    self:RefreshBigRewardUI()
    self:RefreshNodes()
end
--endregion public

