--endregion private

--region helper
function ActivityDirectDrawRewardContentNode:RefreshBigRewardUI()
    local GoodNode = self.BigReward.transform:Find("Root/ActivityDirectDrawRewardNode/Root/GoodNode")
    ---@type GoodNodeMB
    local scr = CfUtils.GetLuaScr(GoodNode, "Game.Behaviours.GoodNodeMB")
    scr:Reload({
        goodsId = self.dojo.playerChoseCardId,
        --text = string.format("x%d", 1),
        --isShowNo = false
    })
    scr:SetClickButtonAction(function()
        self:OnClickBigRewardHandler()
    end)

    local isPlayAnim = checkBool(KCookie.Get(Constants.DirectDrawResearchChooseChange))
    if isPlayAnim then
        CfUtils.StartCoroutineWithBlocker(function()
            CfUtils.PlayAnimation(self.BigReward, "ActivityDirectDrawMainDialog11200101_BigReward_Refresh")
            cs_coroutine.yield_return(WaitForSeconds(1))
            KCookie.Set(Constants.DirectDrawResearchChooseChange, false)
            GameUtils.Toast(localize("研究武装方向已变更"))
        end)
    end
end

function ActivityDirectDrawRewardContentNode:RefreshNodes()
    local goodsList = {}
    local count = table.count(self.dojo.poolInfo.preview)

    for i = 1, count do
        local t = self.dojo.poolInfo.preview[i]
        local goodsId = t.rewards[1].goodsId
        local itemType = GoodsUtils.GetIdType(goodsId)
        if itemType ~= Constants.IDType.CharacterCard then
            table.insert(goodsList, t)
        end
    end

    for i, item in ipairs(goodsList) do
        if i > 8 then
            break
        end
        local nodeGo = self.controller.transform:Find("ActivityDirectDrawRewardNode"..checkString(i))
        local GoodNode = nodeGo.transform:Find("Root/GoodNode")
        ---@type GoodNodeMB
        local scr = CfUtils.GetLuaScr(GoodNode, "Game.Behaviours.GoodNodeMB")
        scr:Reload({
            goodsId = item.rewards[1].goodsId,
            text = string.format("x%d", item.rewards[1].num),
            isShowNo = true
        })
        scr:SetClickButtonAction(function(goodsId, id)
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            if isTable(vo) then
                GameUtils.ShowCommonTipsBoard(GoodNode, vo.name, vo.desc, vo.quality, vo.id)
            end
        end)
    end
end
--endregion helper

return ActivityDirectDrawRewardContentNode
